generateBuildId: async () => {
    // The Docker build context excludes .git (see .dockerignore), so git
    // isn't available inside the builder stage - the commit is passed in
    // via GIT_COMMIT_SHA instead. Fall back to git directly for local/non-Docker builds.
    if (process.env.GIT_COMMIT_SHA) {
        return process.env.GIT_COMMIT_SHA;
    }
    const { execSync } = await import('node:child_process');
    return execSync('git rev-parse HEAD').toString().trim();
},

